/**
 * chudnovsky-pi-algorithm.ts - Chudnovsky Pi Series.
 *
 * ---------------------------------------------------------------------------
 * What it does
 * ---------------------------------------------------------------------------
 * The Chudnovsky series is a rapidly convergent Ramanujan-type series for 1/pi.
 * Each additional term contributes about fourteen decimal digits. The terms
 * are generated by a recurrence so no giant factorials need to be materialized,
 * and pi is recovered as 426880*sqrt(10005)/S where S is the accumulated sum.
 *
 * ---------------------------------------------------------------------------
 * Complexity
 * ---------------------------------------------------------------------------
 *   Time:  O(k) for k series terms (constant work per term)
 *   Space: O(k) for the displayed term table
 *
 * ---------------------------------------------------------------------------
 * Visualization mapping
 * ---------------------------------------------------------------------------
 *   - Each row of the grid is a series term with its index, value and partial sum.
 *   - The newest row is highlighted and the final row reports pi.
 *   - The final frame carries the pi estimate and the absolute error.
 */

import type { AlgorithmModule, EntityState, VisualEntity, VisualFrame } from "@/types";

interface ChudnovskyInput {
    terms?: number;
}

interface Row {
    index: number;
    term: number;
    sum: number;
    pi: number;
}

const CONSTANT = 426880 * Math.sqrt(10005);
const A0 = 13591409;
const A1 = 545140134;
const POW = Math.pow(640320, 3);

function fmt(value: number): string {
    return Number.isFinite(value) ? value.toPrecision(9) : String(value);
}

/** Compute the Chudnovsky partial sums and pi estimates term by term. */
function compute(terms: number): Row[] {
    const rows: Row[] = [];
    let term = A0;
    let sum = A0;
    rows.push({ index: 0, term, sum, pi: CONSTANT / sum });
    for (let k = 1; k < terms; k += 1) {
        let numerator = 1;
        for (let i = 0; i < 6; i += 1) {
            numerator *= 6 * k - i;
        }
        let denominator = 1;
        for (let j = 0; j < 3; j += 1) {
            denominator *= 3 * k - j;
        }
        denominator *= k * k * k * POW;
        term = -term * (numerator / denominator) * (A0 + A1 * k) / (A0 + A1 * (k - 1));
        sum += term;
        rows.push({ index: k, term, sum, pi: CONSTANT / sum });
    }
    return rows;
}

function makeEntities(rows: Row[], done: boolean): VisualEntity[] {
    const entities: VisualEntity[] = [];
    for (const row of rows) {
        const values: Array<[string, number]> = [
            ["k", row.index],
            ["term", row.term],
            ["sum", row.sum],
            ["pi", row.pi],
        ];
        values.forEach(([name, value], col) => {
            entities.push({
                id: `cell-${row.index}-${col}`,
                type: "cell" as const,
                label: `${name}=${fmt(value)}`,
                value,
                state: (done ? "sorted" : row === rows[rows.length - 1] ? "highlight" : "idle") as EntityState,
                x: 0,
                y: 0,
                width: 0,
                height: 0,
                metadata: { row: row.index, col },
            });
        });
    }
    return entities;
}

function* run(input: unknown): Generator<VisualFrame, void, unknown> {
    const task = (input as ChudnovskyInput | null) ?? {};
    const terms = typeof task.terms === "number" && task.terms > 0
        ? Math.max(1, Math.trunc(task.terms))
        : 3;
    const allRows = compute(terms);

    for (let i = 0; i < allRows.length; i += 1) {
        const visible = allRows.slice(0, i + 1);
        const row = allRows[i];
        yield {
            stepNumber: i,
            entities: makeEntities(visible, false),
            edges: [],
            description: `Term ${row?.index ?? 0}: the partial sum gives pi about ${fmt(row?.pi ?? 0)}.`,
            codeLineNumber: i === 0 ? 0 : 3,
            layout: "grid",
            meta: {
                rows: visible.length,
                cols: 4,
                term: row?.index ?? 0,
                pi: row?.pi ?? 0,
                error: Math.abs((row?.pi ?? 0) - Math.PI),
            },
        };
    }

    const final = allRows[allRows.length - 1];
    yield {
        stepNumber: allRows.length,
        entities: makeEntities(allRows, true),
        edges: [],
        description: `Done after ${terms} term(s): pi is about ${fmt(final?.pi ?? 0)} with error ${fmt(Math.abs((final?.pi ?? 0) - Math.PI))}.`,
        codeLineNumber: 5,
        layout: "grid",
        meta: {
            rows: allRows.length,
            cols: 4,
            pi: final?.pi ?? 0,
            error: Math.abs((final?.pi ?? 0) - Math.PI),
        },
    };
}

const module: AlgorithmModule = {
    id: "chudnovsky-pi-algorithm",
    name: "Chudnovsky Pi Algorithm",
    category: "math",
    complexity: { time: "O(k)", space: "O(k)" },
    defaultInput: { terms: 3 },
    visualType: "grid",
    run,
    pseudocode: [
        "set the constant C to 426880 times sqrt(10005)",
        "start the sum at 13591409 and emit the first estimate C/S",
        "for each later term k, update it by the factorial ratio times the linear factor",
        "add the signed term to the running sum",
        "emit the estimate C/S for the new partial sum",
        "done: report the final pi estimate",
    ],
    education: {
        intuition:
            "The Chudnovsky brothers found a Ramanujan-type identity in which each term of an infinite series for 1/pi is worth roughly fourteen decimal digits. Instead of computing enormous factorials directly, each term is derived from the previous one with a short ratio, so a handful of terms gives double-precision pi.",
        invariants: [
            "The constant C equals 426880 times the square root of 10005.",
            "Each term carries the alternating sign through the recurrence.",
            "The partial sum S approaches 1/pi, so C/S approaches pi.",
            "Successive terms shrink by a factor of about 10 to the power negative fourteen.",
        ],
        correctness:
            "The Chudnovsky identity states that 1/pi equals 12 divided by sqrt(10005) times the infinite sum of the generated terms. Rewriting gives pi = C/S. The recurrence is algebraically identical to the closed-form factorial expression, so accumulating the terms implements the identity exactly and truncation error is bounded by the tail of a geometrically shrinking series.",
        complexityRationale:
            "Each term is produced from a fixed number of multiplications, independent of k, so k terms cost O(k) time. Keeping every emitted term and partial sum in the table uses O(k) space.",
        uses: [
            "Setting pi world records with binary splitting implementations",
            "Testing arbitrary-precision arithmetic libraries",
            "Teaching rapidly convergent series for mathematical constants",
        ],
        references: [
            "Chudnovsky and Chudnovsky, The Computation of Classical Constants, 1989",
            "Borwein and Borwein, Pi and the AGM, chapter on Ramanujan-type series",
        ],
        workedExample:
            "With one term S = 13591409 and pi is about 3.141592730013306. Adding the second term, roughly -2.5 times 10 to the minus seven, brings the estimate to within 1e-13 of the true value of pi.",
    },
};

export default module;
